scripts.lcg_iterate:
def solve(inputs: dict) -> float:
    s = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = int(inputs['K'])
    for _ in range(K):
        s = (A * s + B) % M
    return float(s)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    N = int(inputs['N'])
    MOD = int(inputs['MOD'])
    result = 1
    for i in range(2, N + 1):
        result = (result * i) % MOD
    return float(result)

scripts.gcd_list:
def solve(inputs: dict) -> float:
    import math
    vals = [147272720, 230032320, 256567360, 308520800, 286716080]
    result = vals[0]
    for v in vals[1:]:
        result = math.gcd(result, v)
    return float(result)

